import * as THREE from 'three/webgpu';
import { texture, uv, positionLocal, vec3, float, MeshStandardNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-list-row';
  group.position.set(1.25, -0.19999999999999996, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const imageUrl = '/prism-mock/home/nodes/parallax-stack.png';
  const depthUrl = '/prism-mock/home/nodes/parallax-stack.depth.png';

  const colorMap = ctx.textureLoader.load(imageUrl);
  const depthMap = ctx.textureLoader.load(depthUrl);
  colorMap.colorSpace = THREE.SRGBColorSpace;

  const geometry = new THREE.PlaneGeometry(3.2, 0.5, 64, 64);

  const displacementAmount = float(0.08);
  const dispTex = texture(depthMap, uv()).r;
  const displacedPosition = positionLocal.add(
    vec3(0.0, 0.0, dispTex.sub(0.5).mul(displacementAmount))
  );

  const material = new MeshStandardNodeMaterial();
  material.colorNode = texture(colorMap, uv());
  material.positionNode = displacedPosition;
  material.metalness = 0.5;
  material.roughness = 0.55;
  material.clearcoat = 0.2;
  material.side = THREE.DoubleSide;

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'pricing-row-plane';
  group.add(plane);

  // subtle divider line beneath the row
  const dividerGeo = new THREE.PlaneGeometry(3.2, 0.01);
  const dividerMat = new MeshStandardNodeMaterial();
  dividerMat.colorNode = vec3(0.91, 0.925, 0.949);
  dividerMat.metalness = 0.3;
  dividerMat.roughness = 0.6;
  const divider = new THREE.Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -0.28, 0.001);
  divider.name = 'pricing-row-divider';
  group.add(divider);

  // accent rim light
  const rimLight = new THREE.PointLight(0xff2a38, 0.6, 3);
  rimLight.position.set(-1.2, 0.3, 0.6);
  group.add(rimLight);

  // apply cinematic primitives
  const primitivesApplied = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      const fn = ctx.primitives[prim.name];
      if (fn) {
        fn(group, prim.params || {});
        primitivesApplied.push(prim.name);
      }
    });
  }

  // ensure parallax-scroll present
  if (!primitivesApplied.includes('parallax-scroll') && ctx.primitives['parallax-scroll']) {
    ctx.primitives['parallax-scroll'](group, { intensity: 0.4 });
  }

  let hoverTween = null;
  const baseY = group.position.y;

  const handlers = {};

  handlers.onPointerOver = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseY + 0.15,
      duration: 0.5,
      ease: 'power3.out',
    });
  };

  handlers.onPointerOut = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(group.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power3.out',
    });
  };

  handlers.onClick = () => {
    if (ctx.emit) {
      ctx.emit('hub-pricing.select', { source: 'hub-pricing-list-row' });
    }
    gsap.fromTo(
      group.scale,
      { x: 1, y: 1, z: 1 },
      { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out', yoyo: true, repeat: 1 }
    );
  };

  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    geometry.dispose();
    material.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    colorMap.dispose();
    depthMap.dispose();
  };

  return group;
}
